    let property = GA4_PROPERTY_ID_DEFAULT, pinned = false;
    try { const c = await d1all(env.AUDIT, "SELECT value FROM ops_config WHERE key = 'ga4_property_id'"); if (c.length && /^\d+$/.test(String(c[0].value).trim())) { property = String(c[0].value).trim(); pinned = true; } } catch (e) { console.log(JSON.stringify({ worker: NAME, where: "ga4Ingest:property", note: reachErr(e) })); }
