    method: "POST",
    headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
    body: JSON.stringify({ metrics: [{ name: "activeUsers" }], dimensions: [{ name: "unifiedScreenName" }], limit: 10 }),
    signal: AbortSignal.timeout(15000)
