  stmts.push(A.prepare(upsert + " WHERE ops_config.value IS NULL OR ops_config.value = ''").bind(Q08_REVIEW_KEY, JSON.stringify(m), "Q08-REVIEW-2026-10-31 decision (agent_issues 1716), written once by " + m.by));
