  { rule: "Secrets", what: "no key is minted, rotated, deleted or committed outside the secret lease; a service uses its own binding props, never a copy of another service's secret", enforced_by: "qnfo-deploy-guard /secret-lock, INTERNAL-CALLER-PROPS-1" },
  { rule: "Work claims", what: "one writer per file or issue at a time, extended by token and released on merge", enforced_by: "qnfo-deploy-guard /work-lock, qnfo-audit.work_claims" },
  { rule: "Control plane", what: "qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-containers-pilot, qnfo-gateway, qnfo-ai, qnfo-autonomy-scorer, qnfo-observability, qnfo-code-orchestrator and qnfo-code-agent run the full suite set on every change and are canaried; a self-merge needs the worker's versioned /health", enforced_by: "scripts/run-suites.mjs CONTROL_PLANE, ops_config control_plane_self_merge" },
  { rule: "Personal / research separation", what: "owner documents live only in qnfo-identity and the personal plane stays out of the shared audit database", enforced_by: "IDENTITY-STORE-1, personal-life" },
  { rule: "Outreach consent", what: "suppression and opt-out are honoured; posting stays inside each platform's automation terms", enforced_by: "qnfo-social gates, qnfo-subscribers" },
  { rule: "Governance by pull request", what: "CLAUDE.md, the charter and the doctrine change by pull request with a version bump; a loop's own scope widens through the canonical path (pull request, migration, canary), never by editing harness permissions", enforced_by: "charter-guard, DOCTRINE-1 readings (f), (o)" }
