var CONTENT_CSS = ".cp-line{list-style:none;margin:0 0 10px;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.cp-ends{grid-template-columns:repeat(auto-fill,minmax(150px,220px))}"
