// OTP-DO-RATE-1 (BP26-EDGE-SECURITY-1): a per-address sliding-window limit for the sign-in endpoints, held in one Durable Object per scope and address, so one
// visitor's guesses or code requests cannot use up the shared hourly budget that the D1 counters keep for the whole fleet (those stay as the global backstop).
// Fail-open when the OTP_LIMITER binding is absent or the object is unreachable: the D1 counters still apply and the owner is never locked out by this layer.
var OtpRateLimiter = class {
  constructor(state) {
    this.state = state;
  }
  async fetch(request) {
    var b = {};
    try { b = await request.json(); } catch (e) { b = {}; }
    var now = Date.now();
    var win = Math.max(1000, Math.min(Number(b.window_ms) || 600000, 86400000));
    var limit = Math.max(1, Math.min(Number(b.limit) || 5, 100));
    var hits = (await this.state.storage.get("hits")) || [];
    hits = hits.filter(function (t) { return now - t < win; });
    if (hits.length >= limit) {
      await this.state.storage.put("hits", hits);
      return Response.json({ ok: false, retry_after_ms: Math.max(0, win - (now - hits[0])) });
    }
    hits.push(now);
    await this.state.storage.put("hits", hits);
    await this.state.storage.setAlarm(now + win + 1000);
    return Response.json({ ok: true, remaining: limit - hits.length });
  }
  async alarm() {
    await this.state.storage.deleteAll();
  }
};
async function otpRateLimit(env, request, scope, limit, windowMs) {
  try {
    if (!env.OTP_LIMITER) return { ok: true, skipped: true };
    var ip = request.headers.get("CF-Connecting-IP") || "unknown";
    var stub = env.OTP_LIMITER.get(env.OTP_LIMITER.idFromName(scope + ":" + ip));
    var r = await stub.fetch("https://otp-limiter/hit", { method: "POST", body: JSON.stringify({ limit: limit, window_ms: windowMs }) });
    var j = await r.json();
    return j && typeof j.ok === "boolean" ? j : { ok: true, skipped: true };
  } catch (e) {
    return { ok: true, skipped: true, error: String(e && e.message || e).slice(0, 120) };
  }
}
function otpLimited(rl) {
  return { ok: false, status: 429, error: "Too many attempts from this address; wait " + Math.max(1, Math.ceil((rl.retry_after_ms || 600000) / 60000)) + " minutes." };
}
